import{_ as a,o as t,c as o,ao as i}from"./chunks/framework.v97kZSPT.js";const _=JSON.parse('{"title":"Pair copulas","description":"","frontmatter":{},"headers":[],"relativePath":"bestiary/pairs/overview.md","filePath":"bestiary/pairs/overview.md","lastUpdated":null}'),s={name:"bestiary/pairs/overview.md"};function r(l,e,n,c,d,p){return t(),o("div",null,[...e[0]||(e[0]=[i('<h1 id="Pair-copulas" tabindex="-1">Pair copulas <a class="header-anchor" href="#Pair-copulas" aria-label="Permalink to &quot;Pair copulas {#Pair-copulas}&quot;">​</a></h1><p>Pair copulas are the bivariate building blocks attached to vine edges. <code>PairCopula</code> is an alias for <code>Copulas.Copula{2}</code>, so the package uses the bivariate families provided by <code>Copulas.jl</code> while adding vine-oriented conditional kernels and selection logic.</p><p>The default automatic-selection set is intentionally smaller than the complete parametric catalog. It receives the strongest external correctness coverage and includes Gaussian, Student-t, Clayton, Gumbel, Frank, Joe, BB1, BB6, BB7, and BB8. Independence is controlled separately.</p><p>Use <code>family_set=:all</code> to expose the broader parametric set, or pass an explicit tuple of families when the candidate set is part of the model specification.</p>',4)])])}const h=a(s,[["render",r]]);export{_ as __pageData,h as default};
